#!/usr/bin/env python3
"""Ambient Intelligence Indexer for Local Transcripts"""

import json
import re
from pathlib import Path
from datetime import datetime
from collections import defaultdict

class AmbientIndexer:
    def __init__(self):
        self.people = set()
        self.organizations = set()
        self.projects = set()
        self.dates = []
        self.relationships = []
        self.conversations = []
        self.markers = {}

    def parse_transcripts(self, input_dir):
        """Read all transcript files and extract data."""
        transcript_files = sorted(input_dir.glob('*.txt'))

        for filepath in transcript_files:
            content = filepath.read_text(encoding='utf-8')
            self._parse_file(filepath.name, content)

    def _parse_file(self, filename, content):
        """Parse a single transcript file."""
        lines = content.strip().split('\n')
        marker = None
        messages = []

        for line in lines:
            if line.startswith('MARKER:'):
                marker = line.split(':', 1)[1]
            elif line.strip():
                messages.append(line)

        if marker:
            self.markers[marker] = filename

        # Parse messages for entities
        for msg in messages:
            self._extract_from_message(msg)

        self.conversations.append({
            'file': filename,
            'marker': marker,
            'messages': messages
        })

    def _extract_from_message(self, msg):
        """Extract entities from a single message."""
        # Extract date
        date_match = re.search(r'\[(\d{4}-\d{2}-\d{2})', msg)
        if date_match:
            self.dates.append(date_match.group(1))

        # Extract speaker
        speaker_match = re.search(r'\] (\w+):', msg)
        if speaker_match:
            speaker = speaker_match.group(1)
            self.people.add(speaker)

        # Extract text content after speaker
        text_match = re.search(r': (.+)$', msg)
        if text_match:
            text = text_match.group(1).lower()

            # Known organizations
            if 'orion labs' in text:
                self.organizations.add('Orion Labs')

            # Known projects
            if 'northstar' in text:
                self.projects.add('Northstar')

    def build_relationships(self):
        """Build relationship graph from extracted data."""
        # works_on relationships (from explicit statements)
        # "Northstar is owned by Priya and Sam" -> Priya works_on Northstar, Sam works_on Northstar
        for conv in self.conversations:
            for msg in conv['messages']:
                if 'northstar is owned by' in msg.lower():
                    # Extract names after "owned by"
                    match = re.search(r'owned by (.+?)(?:\.|$)', msg, re.IGNORECASE)
                    if match:
                        names_text = match.group(1)
                        if 'priya' in names_text.lower():
                            self.relationships.append({
                                'from': 'Priya',
                                'to': 'Northstar',
                                'type': 'works_on'
                            })
                            self.people.add('Priya')
                        if 'sam' in names_text.lower():
                            self.relationships.append({
                                'from': 'Sam',
                                'to': 'Northstar',
                                'type': 'works_on'
                            })
                            self.people.add('Sam')

                # "Northstar is related to Orion Labs via the pilot contract"
                if 'northstar' in msg.lower() and 'orion labs' in msg.lower():
                    self.relationships.append({
                        'from': 'Northstar',
                        'to': 'Orion Labs',
                        'type': 'client_of'
                    })

        # mentioned_with relationships (people mentioned in same conversation)
        for conv in self.conversations:
            speakers_in_conv = set()
            for msg in conv['messages']:
                speaker_match = re.search(r'\] (\w+):', msg)
                if speaker_match:
                    speakers_in_conv.add(speaker_match.group(1))

            # Create mentioned_with edges between all speakers in same conversation
            speakers_list = sorted(speakers_in_conv)
            for i, s1 in enumerate(speakers_list):
                for s2 in speakers_list[i+1:]:
                    self.relationships.append({
                        'from': s1,
                        'to': s2,
                        'type': 'mentioned_with'
                    })

    def get_recent_conversations_about(self, topics):
        """Get most recent conversations about specific topics."""
        relevant = []
        for conv in reversed(self.conversations):  # Most recent first
            conv_text = ' '.join(conv['messages']).lower()
            for topic in topics:
                if topic.lower() in conv_text:
                    relevant.append(conv)
                    break
        return relevant

    def generate_context_packet(self, project_name):
        """Generate a Context Packet for the specified project."""
        # Get conversations mentioning the project
        project_convs = []
        for conv in self.conversations:
            conv_text = ' '.join(conv['messages']).lower()
            if project_name.lower() in conv_text:
                project_convs.append(conv)

        # Get most recent about deadline shift and client onboarding
        recent_topics = self.get_recent_conversations_about(['deadline', 'onboarding'])

        # Filter relationships related to the project
        project_relationships = [
            r for r in self.relationships 
            if project_name in [r['from'], r['to']]
        ]

        # Build resolved entities
        resolved_entities = {
            'people': sorted(list(self.people)),
            'organizations': sorted(list(self.organizations)),
            'projects': sorted(list(self.projects)),
            'dates': sorted(list(set(self.dates)))
        }

        packet = {
            'project': project_name,
            'generated_at': datetime.now().isoformat(),
            'recent_conversations': project_convs,
            'resolved_entities': resolved_entities,
            'relationships': project_relationships,
            'relevant_history': recent_topics,
            'markers': self.markers
        }

        return packet

    def generate_searchable_summary(self):
        """Generate a searchable summary with conversation snippets."""
        summary = {
            'index_version': '1.0',
            'total_conversations': len(self.conversations),
            'entities': {
                'people': sorted(list(self.people)),
                'organizations': sorted(list(self.organizations)),
                'projects': sorted(list(self.projects)),
                'dates': sorted(list(set(self.dates)))
            },
            'snippets': [],
            'search_index': {}
        }

        # Create snippets for each conversation
        for conv in self.conversations:
            for msg in conv['messages']:
                summary['snippets'].append({
                    'file': conv['file'],
                    'marker': conv['marker'],
                    'text': msg
                })

        # Build simple search index
        for snippet in summary['snippets']:
            words = re.findall(r'\w+', snippet['text'].lower())
            for word in words:
                if word not in summary['search_index']:
                    summary['search_index'][word] = []
                summary['search_index'][word].append(snippet['text'][:100])

        return summary


def main():
    input_dir = Path('input_conversations')
    output_dir = Path('output')
    output_dir.mkdir(exist_ok=True)

    # Read manifest
    manifest = json.loads(Path('input_manifest.json').read_text())
    project_name = manifest.get('project', 'Northstar')

    print(f"Indexing conversations for project: {project_name}")

    # Initialize indexer
    indexer = AmbientIndexer()

    # Parse transcripts
    indexer.parse_transcripts(input_dir)

    # Build relationships
    indexer.build_relationships()

    # Generate context packet
    context_packet = indexer.generate_context_packet(project_name)

    # Generate searchable summary
    searchable_summary = indexer.generate_searchable_summary()

    # Write outputs
    with open(output_dir / 'context_packet.json', 'w') as f:
        json.dump(context_packet, f, indent=2)
    print(f"Written: {output_dir / 'context_packet.json'}")

    with open(output_dir / 'searchable_summary.json', 'w') as f:
        json.dump(searchable_summary, f, indent=2)
    print(f"Written: {output_dir / 'searchable_summary.json'}")

    # Write relationship graph
    graph = {
        'nodes': {
            'people': sorted(list(indexer.people)),
            'organizations': sorted(list(indexer.organizations)),
            'projects': sorted(list(indexer.projects))
        },
        'edges': indexer.relationships
    }
    with open(output_dir / 'relationship_graph.json', 'w') as f:
        json.dump(graph, f, indent=2)
    print(f"Written: {output_dir / 'relationship_graph.json'}")

    print("\nIndexing complete!")
    print(f"  - People found: {sorted(list(indexer.people))}")
    print(f"  - Organizations found: {sorted(list(indexer.organizations))}")
    print(f"  - Projects found: {sorted(list(indexer.projects))}")
    print(f"  - Relationships: {len(indexer.relationships)}")


if __name__ == '__main__':
    main()
